    title: "Thủ tục lưu sẵn là một kịch bản đã lưu và có thể làm việc ngoài câu truy vấn",
    see: "Hình này thể hiện thủ tục (stored procedure) và hàm (function). Thủ tục là một chương trình đã lưu, có thể gồm nhiều câu và có thể ghi vào bảng. Hàm do người dùng viết (UDF) trả về một giá trị và không nên giấu một lần quét bảng. Một hàm bọc quanh cột trong WHERE có thể chạy từng dòng và bỏ chỉ mục.",
    scene: "g-sql-proc",
